using System.Globalization;using System.Text;using ClosedXML.Excel;using WhatsBiz.Application.Common.Interfaces;using WhatsBiz.Application.Features.Gst;
namespace WhatsBiz.Infrastructure.Gst;
public sealed class GstExportService:IGstExportService{private static readonly string[] Headers=["Document","Date","Party","GSTIN","Type","HSN/SAC","GST Rate","Quantity","Taxable","CGST","SGST","IGST","CESS","Total Tax","Net Payable"];public byte[]Export(IReadOnlyCollection<GstReportRowDto>rows,string report,string format)=>format.ToLowerInvariant()switch{"excel"or"xlsx"=>Excel(rows,report),"csv"=>Csv(rows),"pdf"=>Pdf(rows,report),_=>throw new ArgumentOutOfRangeException(nameof(format),"Format must be xlsx, csv, or pdf.")};public string ContentType(string format)=>format.ToLowerInvariant()switch{"excel"or"xlsx"=>"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","csv"=>"text/csv","pdf"=>"application/pdf",_=>"application/octet-stream"};private static object?[]Values(GstReportRowDto x)=>[x.DocumentNumber,x.DocumentDate?.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture),x.PartyName,x.PartyGstin,x.SupplyType??x.SourceType,x.HsnCode,x.GstRate,x.Quantity,x.TaxableAmount,x.CgstAmount,x.SgstAmount,x.IgstAmount,x.CessAmount,x.TotalTax,x.NetTaxPayable];private static byte[]Excel(IReadOnlyCollection<GstReportRowDto>rows,string report){using var w=new XLWorkbook();var s=w.AddWorksheet(report[..Math.Min(report.Length,31)]);for(var i=0;i<Headers.Length;i++)s.Cell(1,i+1).Value=Headers[i];var n=2;foreach(var x in rows){var v=Values(x);for(var i=0;i<v.Length;i++)s.Cell(n,i+1).Value=XLCellValue.FromObject(v[i],CultureInfo.InvariantCulture);n++;}s.Row(1).Style.Font.Bold=true;s.SheetView.FreezeRows(1);s.Columns().AdjustToContents();using var m=new MemoryStream();w.SaveAs(m);return m.ToArray();}private static byte[]Csv(IReadOnlyCollection<GstReportRowDto>rows){static string E(object?x)=>$"\"{Convert.ToString(x,CultureInfo.InvariantCulture)?.Replace("\"","\"\"")}\"";var b=new StringBuilder().AppendLine(string.Join(',',Headers.Select(E)));foreach(var x in rows)b.AppendLine(string.Join(',',Values(x).Select(E)));return Encoding.UTF8.GetBytes(b.ToString());}private static byte[]Pdf(IReadOnlyCollection<GstReportRowDto>rows,string report){var lines=new List<string>{string.Create(CultureInfo.InvariantCulture,$"GST Report: {report}"),string.Create(CultureInfo.InvariantCulture,$"Generated: {DateTimeOffset.Now:yyyy-MM-dd HH:mm}")};lines.AddRange(rows.Take(35).Select(x=>string.Create(CultureInfo.InvariantCulture,$"{x.DocumentNumber??x.HsnCode??x.SupplyType}  Taxable {x.TaxableAmount:0.00}  GST {(x.CgstAmount+x.SgstAmount+x.IgstAmount+x.CessAmount):0.00}")));var content=new StringBuilder("BT /F1 9 Tf 40 800 Td ");foreach(var line in lines)content.Append(CultureInfo.InvariantCulture,$"({line.Replace("\\","\\\\").Replace("(","\\(").Replace(")","\\)")}) Tj 0 -18 Td ");content.Append("ET");var objects=new[]{"<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>",string.Create(CultureInfo.InvariantCulture,$"<< /Length {Encoding.ASCII.GetByteCount(content.ToString())} >>\nstream\n{content}\nendstream"),"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"};var b=new StringBuilder("%PDF-1.4\n");var offsets=new List<int>{0};for(var i=0;i<objects.Length;i++){offsets.Add(Encoding.ASCII.GetByteCount(b.ToString()));b.Append(CultureInfo.InvariantCulture,$"{i+1} 0 obj\n{objects[i]}\nendobj\n");}var xref=Encoding.ASCII.GetByteCount(b.ToString());b.Append(CultureInfo.InvariantCulture,$"xref\n0 {objects.Length+1}\n0000000000 65535 f \n");foreach(var o in offsets.Skip(1))b.Append(CultureInfo.InvariantCulture,$"{o:D10} 00000 n \n");b.Append(CultureInfo.InvariantCulture,$"trailer << /Size {objects.Length+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF");return Encoding.ASCII.GetBytes(b.ToString());}}
